function excludedContracts(){const used=new Set(activeContracts());return contracts.slice(0,15).map(x=>x[0]).filter(n=>!used.has(n));}
function recordScheduleChange(type,before,details={}){state.scheduleChanges=state.scheduleChanges||[];state.scheduleChanges.push({at:new Date().toISOString(),roundIndex:state.rounds.length,type,before:[...before],after:[...state.contracts],...details});}
function addFutureContracts(numbers){if(state.mode!=='mini'||state.rounds.length>=totalRounds())return false;const allowed=new Set(excludedContracts()),add=[...new Set(numbers.map(Number))].filter(n=>allowed.has(n));if(!add.length)return false;const before=[...state.contracts],has16=before.at(-1)===16;state.contracts=[...before.filter(n=>n!==16),...add,...(has16?[16]:[])];recordScheduleChange('add',before,{added:add});persist();return true;}
function replaceFutureContract(removeContract,addContract){removeContract=Number(removeContract);addContract=Number(addContract);if(state.mode!=='mini'||removeContract===16||addContract===16||!excludedContracts().includes(addContract))return false;const idx=state.contracts.indexOf(removeContract);if(idx<state.rounds.length||idx<0)return false;const before=[...state.contracts];state.contracts[idx]=addContract;recordScheduleChange('replace',before,{removed:[removeContract],added:[addContract]});persist();return true;}
function playAllRemaining(){if(state.mode!=='mini')return false;const add=excludedContracts();if(!add.length)return false;const before=[...state.contracts],has16=before.at(-1)===16;state.contracts=[...before.filter(n=>n!==16),...add,...(has16?[16]:[])];recordScheduleChange('play_all',before,{added:add});persist();return true;}
function closeEarly(){if(state.rounds.length>=totalRounds()||activeContracts()[state.rounds.length]===16)return false;const before=[...activeContracts()],played=before.slice(0,state.rounds.length);state.contracts=[...played,16];recordScheduleChange('close_early',before,{removed:before.slice(state.rounds.length).filter(n=>n!==16)});persist();resetDraft();return true;}
async function finishGameNow(){
 if(!state.players?.length||!state.rounds?.length||gameFinished()||spectator)return false;
 if(sharedCode&&shareAccess?.code!==sharedCode)return false;
 const before=[...activeContracts()],played=state.rounds.map(r=>Number(r.contract));
 if(played.some(n=>!Number.isInteger(n)||n<1||n>16)||new Set(played).size!==played.length)return false;
 if(sharedCode){
  try{
   const remote=await ShareService.room(sharedCode);
   if(!remote?.state||remote.current_round?.contract){toast(lt('Concludi prima la mano in corso.','Finish the active round first.','Önce devam eden eli bitir.'));return false;}
   if(remote.state.createdAt!==state.createdAt||remote.state.rounds?.length!==played.length||Number(remote.state.revision||0)!==Number(state.revision||0)){
    await refreshSharedGame();toast(lt('La partita è cambiata: verifica e riprova.','The game has changed: review and retry.','Oyun değişti: kontrol edip tekrar deneyin.'));return false;
   }
   const updated={...remote.state,contracts:played,closedEarlyAt:new Date().toISOString(),earlyFinishPlannedRounds:before.length,
    scheduleChanges:[...(remote.state.scheduleChanges||[]),{at:new Date().toISOString(),roundIndex:played.length,type:'finish_now',before,after:played,plannedRounds:before.length,playedRounds:played.length}],
    revision:Number(remote.state.revision||0)+1,maxRounds:Math.max(Number(remote.state.maxRounds)||0,played.length)};
   const saved=await ShareService.upsert(shareAccess,updated);
   if(saved!==true){toast(lt('Chiusura non salvata nel cloud. Riprova.','Closing was not saved to the cloud. Retry.','Bitiş buluta kaydedilmedi.'));return false;}
   await refreshSharedGame();return gameFinished();
  }catch{toast(lt('Chiusura non riuscita: nessuna mano cancellata.','Unable to finish: no rounds deleted.','Bitirilemedi: el silinmedi.'));return false;}
 }
 state.contracts=played;state.closedEarlyAt=new Date().toISOString();state.earlyFinishPlannedRounds=before.length;
 recordScheduleChange('finish_now',before,{plannedRounds:before.length,playedRounds:played.length});
 delete state.currentRoundStartedAt;delete state.currentRoundContract;delete state.currentRoundRandomlyDrawn;
 persist();resetDraft();archiveCompletedGame();render();return true;
}
