function rememberOwnedGame(access){if(!access?.code||!access?.ownerToken)return;const games=loadOwnedGames().filter(x=>x.code!==access.code);games.unshift({code:access.code,ownerToken:access.ownerToken});localStorage.setItem(OWNED_GAMES_KEY,JSON.stringify(games));}
function forgetOwnedGame(code){localStorage.setItem(OWNED_GAMES_KEY,JSON.stringify(loadOwnedGames().filter(x=>x.code!==code)));}
