const DELETED_OWNED_CODES_KEY=testMode?'amerikano-test-deleted-owned-codes-v1':'amerikano-deleted-owned-codes-v1';
function deletedOwnedCodes(){try{const v=JSON.parse(localStorage.getItem(DELETED_OWNED_CODES_KEY));return new Set(Array.isArray(v)?v.map(x=>String(x).toUpperCase()):[]);}catch{return new Set();}}
