const AUTO_SYNC_REJECTED_KEY=testMode?'amerikano-test-sync-rejected-v1':'amerikano-auto-sync-rejected-v1';
function latestSnapshotsOnly(queue,fallback){const last=new Map();queue.forEach((item,i)=>last.set((item.access||fallback)?.code||item.id,i));return queue.filter((item,i)=>last.get((item.access||fallback)?.code||item.id)===i);}
function rejectSyncItem(item){try{const kept=JSON.parse(localStorage.getItem(AUTO_SYNC_REJECTED_KEY))||[];kept.push({...item,rejectedAt:new Date().toISOString()});localStorage.setItem(AUTO_SYNC_REJECTED_KEY,JSON.stringify(kept.slice(-50)));}catch{}saveAutoSyncQueue(loadAutoSyncQueue().filter(x=>x.id!==item.id));toast(lt('Una partita non è stata accettata dal cloud: resta salvata sul telefono.','A game was not accepted by the cloud: it stays saved on the phone.','Bir oyun bulut tarafından kabul edilmedi: telefonda kayıtlı kalıyor.'));}
const HISTORY_MIGRATION_KEY=testMode?'amerikano-test-history-migration-v1':'amerikano-history-migration-v1';
function loadHistoryMigration(){try{const v=JSON.parse(localStorage.getItem(HISTORY_MIGRATION_KEY));return v&&typeof v==='object'?v:{};}catch{return {};}}
function pendingSyncWarning(){if(!spectator&&loadAutoSyncQueue().length&&!window.ShareService?.configured?.())toast(lt('Partite in attesa: configura Supabase per sincronizzarle','Games waiting: configure Supabase to sync them','Bekleyen oyunlar: eşitlemek için Supabase ayarlarını yapın'));}
// Una partita gia' letta dal cloud non va mai migrata come una nuova partita.
// Le copie conservate localmente restano leggibili e nei backup, ma non vengono reinviate.
function isImportedHistoryCopy(game){
 const id=String(game?.id||'');
 return game?.fromCloud===true||/^(cloud|remote)-[A-Z2-9]{6,14}$/i.test(id);
}
function unsafeHistoricalSyncItem(item){
 const game=item?.state||{};
 if(isImportedHistoryCopy(game))return true;
 const source=String(game.shareCode||'').toUpperCase();
 const target=String(item?.access?.code||'').toUpperCase();
 return Boolean(source&&source!==target);
}
function safeAutoSyncQueue(){
 const queue=loadAutoSyncQueue();
 const deleted=deletedOwnedCodes();
 const unsafe=queue.filter(item=>unsafeHistoricalSyncItem(item)||deleted.has(String(item?.access?.code||'').toUpperCase()));
 if(!unsafe.length)return queue;
 const safe=queue.filter(item=>!unsafeHistoricalSyncItem(item)&&!deleted.has(String(item?.access?.code||'').toUpperCase()));
 try{
  let previously=[];try{const v=JSON.parse(localStorage.getItem(AUTO_SYNC_REJECTED_KEY));if(Array.isArray(v))previously=v;}catch{}
  const rejectedAt=new Date().toISOString();
  const quarantined=unsafe.map(item=>({...item,rejectedAt,reason:deleted.has(String(item?.access?.code||'').toUpperCase())?'deleted_owned_game_never_upload':'imported_cloud_history_never_upload'}));
  writeLocalStorageAtomically([
   [AUTO_SYNC_REJECTED_KEY,JSON.stringify([...previously,...quarantined].slice(-100))],
   [AUTO_SYNC_QUEUE_KEY,JSON.stringify(safe)]
  ]);
 }catch{} // Anche senza spazio non inviare le copie gia' importate.
 return safe;
}
function migrateCompletedGamesToSyncQueue(){
 if(spectator||!window.ShareService?.newAccess)return;
 const migration=loadHistoryMigration(),queue=safeAutoSyncQueue(),owned=loadOwnedGames();let changed=false;
 for(const game of loadCompletedGames()){
  if(!game?.id||migration[game.id]||isImportedHistoryCopy(game)||deletedOwnedCodes().has(String(game.shareCode||'').toUpperCase()))continue;
  const sourceCode=String(game.shareCode||'').toUpperCase();
  const existing=sourceCode&&owned.find(x=>x.code===sourceCode&&x.ownerToken);
  // Un codice cloud senza proprieta' non autorizza a creare una nuova copia.
  if(sourceCode&&!existing)continue;
  const access=existing||ShareService.newAccess(testMode);migration[game.id]=access;
  if(!owned.some(x=>x.code===access.code))owned.push({code:access.code,ownerToken:access.ownerToken});
  queue.push({id:game.id+':'+(game.rounds?.length||0),gameId:game.id,roundIndex:game.rounds?.length||0,access,state:JSON.parse(JSON.stringify(game))});changed=true;
 }
 if(changed){
  try{writeLocalStorageAtomically([
   [OWNED_GAMES_KEY,JSON.stringify(owned)],
   [AUTO_SYNC_QUEUE_KEY,JSON.stringify(queue)],
   [HISTORY_MIGRATION_KEY,JSON.stringify(migration)]
  ]);}catch{
   toast(lt('Spazio insufficiente per preparare la sincronizzazione: salva prima un backup completo. Le partite locali sono conservate.','Not enough space to prepare sync: save a full backup first. Local games are preserved.','Senkronizasyon için yeterli alan yok: önce tam yedek kaydedin. Yerel oyunlar korunur.'));
   return false;
  }
  pendingSyncWarning();
 }
 return true;
}
function queueAutomaticSnapshot(){
  if(spectator||!state.players?.length||!window.ShareService?.newAccess||!(state.rounds?.length||state.entryMode==='multi'))return;
  if(!shareAccess){
    shareAccess=ShareService.newAccess(testMode);
    localStorage.setItem(SHARE_KEY,JSON.stringify(shareAccess));
    rememberOwnedGame(shareAccess);
  }
  const gameId=state.archiveId||state.createdAt||'current',roundIndex=state.rounds?.length||0;
  const item={id:`${shareAccess.code}:${roundIndex}`,gameId,roundIndex,access:shareAccess,state:JSON.parse(JSON.stringify(state))};
  const queue=loadAutoSyncQueue().filter(x=>x.id!==item.id);queue.push(item);saveAutoSyncQueue(queue);
}
