function decimalText(n){const v=Math.round((Number(n)||0)*10)/10;return I18N.language==='en'?String(v):String(v).replace('.',',');}
function weightedGameResult(g,ranking){
 const length=(g.rounds||[]).length;
 const expected=Array.isArray(g.contracts)&&g.contracts.length?g.contracts.length:length;
 const weight=length>0&&length===expected?length:0;
 const count=ranking.length;
 // Scala per posizione parametrica: il primo conserva il 100%, l'ultimo prende sempre 0.
 // I valori intermedi rispettano la scala storica 60%, 40%, 20%, senza assegnare
 // il valore della vecchia quarta posizione all'ultimo in una partita a quattro.
 const factors=Array.from({length:count},(_,i)=>i===count-1?0:[1,.6,.4,.2][i]||0);
 const scores=ranking.map(r=>Number(r.total)||0);
 const best=Math.min(...scores),worst=Math.max(...scores),points={};
 ranking.forEach(r=>{
  const score=Number(r.total)||0;
  const place=scores.filter(other=>other<score).length;
  // Pari merito all'ultimo posto: tutti 0. Se tutti sono pari, restano primi ex aequo.
  const factor=score===worst&&worst>best?0:(factors[place]||0);
  points[r.name]=Math.round(weight*factor);
 });
 return {weight,points};
}
var statsFilter={group:'all',duration:'all',order:'standing'};
