function statisticsGames(){return allCompletedGames().filter(g=>{if(g.testGame)return false;if(statsFilter.group!=='all'&&statsGroupKey(g)!==statsFilter.group)return false;const n=String(g.rounds?.length||0);return statsFilter.duration==='all'||(statsFilter.duration==='other'?!['5','10','16'].includes(n):n===statsFilter.duration);});}

