function statsFilterView(){if(statsFilter.duration!=='all'&&!statsDurations().some(([n])=>n===statsFilter.duration))statsFilter.duration='all';const groups=new Map();allCompletedGames().forEach(g=>{const key=statsGroupKey(g);groups.set(key,(groups.get(key)||0)+1);});return `<div class="stats-filters"><label>${lt('Gruppo','Group','Grup')}<select id="stats-group"><option value="all">${lt('Tutti i gruppi','All groups','Tüm gruplar')}</option>${[...groups].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).map(([key,n])=>`<option value="${esc(key)}" ${statsFilter.group===key?'selected':''}>${esc(JSON.parse(key).join(', '))} · ${n}</option>`).join('')}</select></label><label>${lt('Durata','Length','Uzunluk')}<select id="stats-duration">${[['all',lt('Tutte','All','Tümü')],...statsDurations().map(([n,count])=>[n,n+' '+(n==='1'?lt('mano','round','el'):lt('mani','rounds','el'))+' · '+count])].map(([value,label])=>`<option value="${value}" ${statsFilter.duration===value?'selected':''}>${label}</option>`).join('')}</select></label><label>${lt('Classifica','Standings','Sıralama')}<select id="stats-order">${[['standing',lt('Punti classifica','Standings points','Sıralama puanı')],['strength',lt('Forza degli avversari','Opponent strength','Rakip gücü')]].map(([value,label])=>`<option value="${value}" ${statsFilter.order===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`;}
function statsChronology(g){const d=Date.parse(g.endedAt||g.startedAt||g.createdAt);return Number.isFinite(d)?d:0;}
function difficultyRatings(games){const by={};[...games].sort((a,b)=>statsChronology(a)-statsChronology(b)||String(a.shareCode||a.id||JSON.stringify([a.players,a.rounds])).localeCompare(String(b.shareCode||b.id||JSON.stringify([b.players,b.rounds])))).forEach(g=>{const ranked=evRanking(g),weight=weightedGameResult(g,ranked).weight,n=g.players.length;if(!weight||n<2)return;g.players.forEach(name=>by[name]||=( {rating:1000,games:0,items:[]}));const before=g.players.map(name=>by[name].rating),scores=g.players.map(name=>Number(ranked.find(r=>r.name===name)?.total)||0),k=32*Math.sqrt(n-1)*Math.min(16,weight)/16/(n-1);g.players.forEach((name,i)=>{let change=0;g.players.forEach((_,j)=>{if(i===j)return;const actual=scores[i]<scores[j]?1:scores[i]===scores[j]?.5:0,expected=1/(1+10**((before[j]-before[i])/400));change+=k*(actual-expected);});const delta=Math.round(change),x=by[name];x.rating=before[i]+delta;x.games++;x.items.push({when:fmtDateTime(g.startedAt),count:delta,detail:`${weight} ${pl(weight,'mani','rounds','el')} · ${n} ${pl(n,'giocatori','players','oyuncu')} · ${before[i]} → ${x.rating} (${delta>0?'+':''}${delta}) · ${lt('forza avversari prima della partita','opponents before the game','oyun öncesi rakip gücü')}: ${g.players.map((other,j)=>j===i?'':`${other} ${before[j]}`).filter(Boolean).join(', ')}`});});});return by;}
function raceFacts(g,i){const {positions}=evPositions(g),p=positions[i],rank=evRanking(g),score=Number(rank.find(x=>x.name===g.players[i])?.total)||0,sorted=rank.map(r=>Number(r.total)||0).sort((a,b)=>a-b),soleWin=sorted.length>1&&score===sorted[0]&&sorted[0]<sorted[1],wins=(g.rounds||[]).filter(r=>evRoundWinner(r)===i).length;let decisiveGain=0,decisiveRound=0;const rival=soleWin?g.players.indexOf(rank.find(r=>Number(r.total)===sorted[1])?.name):-1;(g.rounds||[]).forEach((r,ri)=>{if(rival<0)return;const gain=(Number(r.results?.[rival]?.total)||0)-(Number(r.results?.[i]?.total)||0);if(gain>decisiveGain){decisiveGain=gain;decisiveRound=ri+1;}});return {leaderHands:p.filter(pos=>pos===0).length,leadTakeovers:p.slice(1).filter((pos,j)=>pos===0&&p[j]>0).length,closeWins:soleWin&&(sorted[1]-sorted[0])<5*(g.rounds?.length||0)?1:0,perfectFinals:soleWin&&evRoundWinner(g.rounds?.at(-1)||{})===i?1:0,maxRoundWins:wins,decisiveGain,decisiveRound};}
