function residualStatisticDetail(name,key,x){const spec=residualStatisticSpecs()[key];if(!spec)return null;const max=['maxRoundWins','decisiveGain'].includes(key),items=statisticsGames().filter(g=>g.players.includes(name)).flatMap(g=>{const i=g.players.indexOf(name),f=raceFacts(g,i),v=f[key];if(!v||max&&v!==x[key])return[];const positions=evPositions(g).positions[i];return [{when:fmtDateTime(g.startedAt),round:key==='decisiveGain'?f.decisiveRound:null,contract:key==='decisiveGain'?evContract(g.rounds[f.decisiveRound-1]):'',count:v,best:max,detail:`${v} · ${g.rounds.length} ${pl(g.rounds.length,'mani','rounds','el')} · ${lt('posizioni','positions','sıralar')}: ${positions.map(p=>p+1+'°').join(' → ')}`}];});return {title:spec[0],meaning:spec[1],how:spec[2],value:x[key],items};}
function contractLeaders(n,rows){
 const records=rows.map(p=>({name:p.name,...contractStatistics(p.name)[n-1]}));
 const eligible=records.filter(x=>x.hands>=3);
 // I riconoscimenti richiedono un confronto attendibile tra almeno due giocatori.
 // La percentuale di vittorie prevale sulla media punti; una parita' non assegna premi.
 if(eligible.length<2)return {records,specialists:[],cursed:[]};
 const best=Math.max(...eligible.map(x=>x.wins/x.hands));
 const worst=Math.min(...eligible.map(x=>x.wins/x.hands));
 const specialists=eligible.filter(x=>x.wins/x.hands===best);
 const cursed=eligible.filter(x=>x.wins/x.hands===worst);
 return {
  records,
  specialists:best>=.6&&specialists.length===1?[specialists[0].name]:[],
  cursed:worst<best&&cursed.length===1?[cursed[0].name]:[]
 };
}
function contractsLeagueView(rows){return `<p class="subtle">${lt('Specialista: miglior percentuale di vittorie (almeno 60%). Mano maledetta: percentuale di vittorie più bassa. Entrambi richiedono almeno 3 mani a giocatore, due giocatori confrontabili e nessun pari merito.','Specialist: highest win rate (at least 60%). Cursed round: lowest win rate. Both require at least 3 rounds per player, two eligible players and no ties.','Uzman: en yüksek kazanma oranı (en az %60). Lanetli el: en düşük kazanma oranı. Her ikisi için oyuncu başına en az 3 el, iki uygun oyuncu ve eşitlik olmaması gerekir.')}</p><div class="award-grid">${contracts.map(([n,title])=>{const info=contractLeaders(n,rows);return `<button class="award-tile contract-tile" data-contract-detail="${n}"><strong>${n}. ${esc(title)}</strong><span>${lt('Specialista','Specialist','Uzman')}: ${esc(info.specialists.join(', ')||'—')}</span><span>${lt('Mano maledetta','Cursed round','Lanetli el')}: ${esc(info.cursed.join(', ')||'—')}</span><span class="award-more">${lt('Dettagli','Details','Ayrıntılar')} ›</span></button>`;}).join('')}</div>`;}
function contractDetailModal(n){const back=statsPosition(),info=contractLeaders(n,statisticsData());closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><h2>${n}. ${esc(contracts[n-1]?.[1]||'')}</h2><p class="subtle">${lt('Vinte: vincitore registrato. Scelte: solo volontarie, non Mini o obblighi. Media punti: totale delle mani ÷ mani giocate (solo dettaglio). Specialista: percentuale di vittorie più alta, almeno 60%; Mano maledetta: percentuale più bassa. Servono almeno 3 mani a giocatore e due giocatori confrontabili. Con parità non si assegna nessun riconoscimento.','Won: recorded winner. Choices: voluntary only; Mini and forced rounds excluded. Average points are shown for information only. Specialist: highest win rate, at least 60%; cursed round: lowest win rate. At least 3 rounds per player and two eligible players are needed. No award is given on ties.','Kazanılan: kayıtlı kazanan. Seçimler: sadece gönüllü; Mini ve zorunlu eller hariç. Puan ortalaması yalnızca bilgi amaçlıdır. Uzman: en yüksek kazanma oranı (en az %60); lanetli el: en düşük oran. Oyuncu başına en az 3 el ve iki uygun oyuncu gerekir. Eşitlikte ödül verilmez.')}</p><div class="position-table-wrap"><table class="position-table"><thead><tr>${[lt('Giocatore','Player','Oyuncu'),lt('Giocate','Played','Oynanan'),lt('Vinte','Won','Kazanılan'),lt('Scelte','Choices','Seçimler'),lt('Media punti','Avg points','Ort. puan')].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${info.records.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.hands}</td><td>${x.wins} (${x.hands?Math.round(x.wins*100/x.hands):0}%)</td><td>${x.choices}</td><td>${x.hands?decimalText(x.points/x.hands):'—'}</td></tr>`).join('')}</tbody></table></div><button class="ghost" id="modal-cancel">← ${lt('Contratti','Contracts','Sözleşmeler')}</button></div></div>`);document.querySelector('#modal-cancel').onclick=()=>{statsReturn=back;statisticsModal();};}
function finalRoundFacts(g,i){const p=evPositions(g).positions[i],last=g.rounds?.at(-1);return {lastHandWins:last&&evRoundWinner(last)===i?1:0,lastCharge:p.length>1&&p.at(-2)===g.players.length-1&&p.at(-1)===0?1:0,lastDrop:p.length>1&&p.at(-2)===0&&p.at(-1)>0?1:0};}
function extendedStatistics(rows,games){const elo=difficultyRatings(games);return rows.map(x=>{let lastHandWins=0,lastCharge=0,lastDrop=0,finish=0;const residual={leaderHands:0,leadTakeovers:0,closeWins:0,perfectFinals:0,maxRoundWins:0,decisiveGain:0};games.filter(g=>g.players.includes(x.name)).forEach(g=>{const i=g.players.indexOf(x.name),facts=finalRoundFacts(g,i);const rf=raceFacts(g,i);for(const key of Object.keys(residual))residual[key]=['maxRoundWins','decisiveGain'].includes(key)?Math.max(residual[key],rf[key]):residual[key]+rf[key];lastHandWins+=facts.lastHandWins;lastCharge+=facts.lastCharge;lastDrop+=facts.lastDrop;const rank=evRanking(g),score=Number(rank.find(r=>r.name===x.name)?.total)||0;finish+=rank.filter(r=>(Number(r.total)||0)<score).length/(Math.max(1,g.players.length-1));});return {...x,...residual,lastHandWins,lastCharge,lastDrop,penalties100:x.hands?Math.round(x.infractions*100/x.hands):0,cleanRate:x.games?Math.round(x.cleanGames*100/x.games):0,finishRate:x.games?Math.round((1-finish/x.games)*100):0,strength:elo[x.name]?.rating??1000,strengthGames:elo[x.name]?.games||0};});}
