function extraStatisticDetail(name,key,x){const residual=residualStatisticDetail(name,key,x);if(residual)return residual;const spec=extraStatisticSpecs()[key];if(!spec)return null;const games=statisticsGames().filter(g=>g.players.includes(name));const items=key==='strength'?(difficultyRatings(statisticsGames())[name]?.items||[]):games.flatMap(g=>{const i=g.players.indexOf(name),facts=finalRoundFacts(g,i),inf=(g.rounds||[]).reduce((n,r)=>n+(Number(r.results?.[i]?.infractions)||0),0),rank=evRanking(g),score=Number(rank.find(r=>r.name===name)?.total)||0,pos=rank.filter(r=>(Number(r.total)||0)<score).length+1;if(['lastHandWins','lastCharge','lastDrop'].includes(key)&&!facts[key])return[];return [{when:fmtDateTime(g.startedAt),count:facts[key]||0,detail:`${g.rounds.length} ${pl(g.rounds.length,'mani','rounds','el')} · ${g.players.length} ${pl(g.players.length,'giocatori','players','oyuncu')} · ${pos}° · ${score} ${pl(score,'punti','points','puan')} · ${inf} ${pl(inf,'penalità','penalties','ceza')}`}];});return {title:spec[0],meaning:spec[1],how:spec[2],value:x[key],items};}
function extraStatisticTiles(x){return Object.entries(extraStatisticSpecs()).map(([key,spec])=>`<button type="button" data-player-stat="${key}" data-player-name="${esc(x.name)}"><b>${x[key]}${['cleanRate','finishRate'].includes(key)?'%':''}</b>${['cleanRate','finishRate','strength'].includes(key)?spec[0]:one(x[key],spec[0])}${key==='strength'?`<small>${x.strengthGames} ${pl(x.strengthGames,'partite','games','oyun')}${x.strengthGames<5?' · '+lt('provvisorio','provisional','geçici'):''}</small>`:''}</button>`).join('');}
function contractStatistics(name){const out=Array.from({length:16},(_,i)=>({contract:i+1,hands:0,wins:0,choices:0,choiceWins:0,points:0}));statisticsGames().forEach(g=>{const i=g.players.indexOf(name);if(i<0)return;g.rounds.forEach((r,ri)=>{const x=out[Number(r.contract)-1];if(!x)return;x.hands++;x.points+=Number(r.results?.[i]?.total)||0;if(evRoundWinner(r)===i)x.wins++;if(evFreeChoice(g,ri)&&evRoundChooser(g,r,ri)===i){x.choices++;if(evRoundWinner(r)===i)x.choiceWins++;}});});return out;}
function playerBreakdownModal(name){const back=statsPosition(),byLength={};statisticsGames().filter(g=>g.players.includes(name)).forEach(g=>{const n=g.rounds.length,x=byLength[n]||=( {games:0,wins:0}),ranking=evRanking(g),best=Math.min(...ranking.map(r=>Number(r.total)||0));x.games++;if((Number(ranking.find(r=>r.name===name)?.total)||0)===best)x.wins++;});closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><p class="eyebrow">${esc(name)}</p><h2>${lt('Durate e contratti','Lengths and contracts','Uzunluklar ve sözleşmeler')}</h2><h3>${lt('Vittorie per durata','Wins by length','Uzunluğa göre galibiyet')}</h3>${Object.entries(byLength).sort((a,b)=>Number(a[0])-Number(b[0])).map(([n,x])=>`<p>${n} ${pl(n,'mani','rounds','el')}: <strong>${x.wins}/${x.games}</strong> · ${Math.round(x.wins*100/x.games)}%</p>`).join('')}<h3>${lt('Rendimento per contratto','Contract performance','Sözleşme performansı')}</h3><p class="subtle">${lt('Giocate e vittorie includono tutte le mani. Scelte: solo volontarie; Mini e obblighi esclusi. Media: punti di gioco dopo raddoppi e penalità.','Played and won include all rounds. Choices: voluntary only; Mini and forced excluded. Average: game points after multipliers and penalties.','Oynanan ve kazanılan tüm elleri içerir. Seçimler: yalnızca gönüllü; Mini ve zorunlu hariç. Ortalama: çarpan ve cezalar sonrası puan.')}</p><div class="position-table-wrap"><table class="position-table"><thead><tr>${[lt('Contratto','Contract','Sözleşme'),lt('Giocate','Played','Oynanan'),lt('Vinte','Won','Kazanılan'),lt('Scelte','Choices','Seçimler'),lt('Vinte scegliendo','Won when chosen','Seçerek kazanılan'),lt('Media punti','Avg points','Ort. puan')].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${contractStatistics(name).map(x=>`<tr><td>${x.contract}. ${esc(contracts[x.contract-1]?.[1]||'')}</td><td>${x.hands}</td><td>${x.wins}</td><td>${x.choices}</td><td>${x.choices?`${x.choiceWins}/${x.choices} (${Math.round(x.choiceWins*100/x.choices)}%)`:'—'}</td><td>${x.hands?decimalText(x.points/x.hands):'—'}</td></tr>`).join('')}</tbody></table></div><button class="ghost" id="modal-cancel">← ${lt('Giocatori','Players','Oyuncular')}</button></div></div>`);document.querySelector('#modal-cancel').onclick=()=>{statsReturn=back;statisticsModal();};}
function noOpenStatistics(games){
 const by={};
 const ordered=[...games].sort((a,b)=>statsChronology(a)-statsChronology(b));
 for(const g of ordered)for(const name of g.players||[])by[name]||={noOpenCount:0,noOpenKnown:0,noOpenCurrentStreak:0,noOpenBestStreak:0,noOpenStreaks:0};
 for(const g of ordered)(g.rounds||[]).forEach(round=>(g.players||[]).forEach((name,i)=>{
  const x=by[name],value=round.results?.[i]?.didNotOpen;
  if(typeof value!=='boolean'){x.noOpenCurrentStreak=0;return;}
  x.noOpenKnown++;
  if(value){x.noOpenCount++;if(!x.noOpenCurrentStreak)x.noOpenStreaks++;x.noOpenCurrentStreak++;x.noOpenBestStreak=Math.max(x.noOpenBestStreak,x.noOpenCurrentStreak);}
  else x.noOpenCurrentStreak=0;
 }));
 for(const x of Object.values(by))x.noOpenRate=x.noOpenKnown?Math.round(x.noOpenCount*100/x.noOpenKnown):null;
 return by;
}
function statisticsData(){
 const games=statisticsGames(),by={};
 games.slice().reverse().forEach(g=>{
  const ranking=g.ranking?.length?g.ranking:gameRanking(g),gameWins={},weighted=weightedGameResult(g,ranking);
  (g.rounds||[]).forEach((round,roundIndex)=>{
   const chooser=Number.isInteger(round.chooser)?round.chooser:((Number.isInteger(g.firstChooser)?g.firstChooser:0)+roundIndex)%(g.players?.length||1),winner=Number.isInteger(round.winner)?round.winner:(round.results||[]).findIndex(x=>x?.winner);
   if(winner>=0)gameWins[winner]=(gameWins[winner]||0)+1;
   g.players.forEach((name,i)=>{
    const x=by[name]||={name,games:0,wins:0,podiums:0,seconds:0,thirds:0,infractions:0,currentStreak:0,bestStreak:0,chosen:0,chosenWins:0,chosenLosses:0,chosenLast:0,couplesChoices:0,stolenWins:0,roundWins:0,bestRoundStreak:0,cutJokers:0,maxCutJokers:0,discardTakes:0,maxDiscardTakes:0,collectorHands:0,soloDominations:0,jokerCloses:0,points:0,rollerCoasterScore:0,worstGameScore:null,bestComeback:0};
    x.roundWins+=winner===i?1:0;x.hands=(x.hands||0)+1;x.worstHand=Math.max(x.worstHand||0,Number(round.results?.[i]?.total)||0);if(winner===i&&round.jokerClose)x.jokerCloses++;const takes=Math.max(0,Math.min(4,Number(round.results?.[i]?.discardTakes)||0));x.discardTakes+=takes;x.maxDiscardTakes=Math.max(x.maxDiscardTakes,takes);if(winner!==i&&takes>=3)x.collectorHands++;if((Number.isInteger(round.cutter)?round.cutter:(chooser-2+g.players.length)%g.players.length)===i){const cj=Math.max(0,Number(round.cutJokers)||0);x.cutJokers+=cj;x.maxCutJokers=Math.max(x.maxCutJokers,cj);}
    if(chooser===i&&evFreeChoice(g,roundIndex)){x.chosen++;if(Number(round.contract)===15&&evFreeChoice(g,roundIndex))x.couplesChoices++;if(winner===i)x.chosenWins++;else if(winner>=0){x.chosenLosses++;const totals=(round.results||[]).map(r=>Number(r?.total));if(totals.length===g.players.length&&totals.every(Number.isFinite)&&totals[i]===Math.max(...totals))x.chosenLast++;}}
    else if(winner===i&&chooser!==i&&evFreeChoice(g,roundIndex))x.stolenWins++;
    by[name]=x;
   });
  });
  ranking.forEach((r,pos)=>{const x=by[r.name]||={name:r.name,games:0,wins:0,podiums:0,seconds:0,thirds:0,infractions:0,currentStreak:0,bestStreak:0,chosen:0,chosenWins:0,chosenLosses:0,chosenLast:0,couplesChoices:0,stolenWins:0,roundWins:0,bestRoundStreak:0,cutJokers:0,maxCutJokers:0,discardTakes:0,maxDiscardTakes:0,collectorHands:0,soloDominations:0,jokerCloses:0,points:0,rollerCoasterScore:0,worstGameScore:null,bestComeback:0};x.weightedGames=(x.weightedGames||0)+weighted.weight;x.weightedWins=(x.weightedWins||0)+(weighted.points[r.name]||0);x.games++;if(pos===0){x.wins++;x.currentStreak++;x.bestStreak=Math.max(x.bestStreak,x.currentStreak);}else x.currentStreak=0;if(pos<3)x.podiums++;x.points+=Number(r.total)||0;x.bestGame=x.bestGame==null?(Number(r.total)||0):Math.min(x.bestGame,Number(r.total)||0);{const k=g.players.indexOf(r.name);if(!(g.rounds||[]).some(round=>(Number(round.results?.[k]?.infractions)||0)>0))x.cleanGames=(x.cleanGames||0)+1;}if(pos===1)x.seconds++;if(pos===2)x.thirds++;const idx=g.players.indexOf(r.name);x.infractions+=(g.rounds||[]).reduce((sum,round)=>sum+(round.results?.[idx]?.infractions||0),0);by[r.name]=x;});
  g.players.forEach((name,i)=>{const x=by[name];let streak=0,best=0;(g.rounds||[]).forEach(round=>{const w=Number.isInteger(round.winner)?round.winner:(round.results||[]).findIndex(r=>r?.winner);streak=w===i?streak+1:0;best=Math.max(best,streak);});x.bestRoundStreak=Math.max(x.bestRoundStreak,best);});
  const handWins=g.players.map((_,i)=>(g.rounds||[]).filter(round=>(Number.isInteger(round.winner)?round.winner:(round.results||[]).findIndex(r=>r?.winner))===i).length);handWins.forEach((wins,i)=>{if(wins>handWins.reduce((sum,n,j)=>sum+(j===i?0:n),0))by[g.players[i]].soloDominations++;});
  const {cumulative,positions}=evPositions(g);
  g.players.forEach((name,i)=>{const pos=positions[i],movement=pos.slice(1).reduce((sum,p,j)=>sum+Math.abs(p-pos[j]),0),finalPos=pos.at(-1)??0,worstEarlier=pos.length>1?Math.max(...pos.slice(0,-1)):finalPos,comeback=Math.max(0,worstEarlier-finalPos);by[name].rollerCoasterScore=Math.max(by[name].rollerCoasterScore,movement);by[name].bestComeback=Math.max(by[name].bestComeback,comeback);if(finalPos===0&&worstEarlier===g.players.length-1&&comeback>0)by[name].highlanderWins=(by[name].highlanderWins||0)+1;by[name].worstGameScore=by[name].worstGameScore===null?cumulative[i]:Math.max(by[name].worstGameScore,cumulative[i]);});
 });
 const noOpen=noOpenStatistics(games);
 return extendedStatistics(Object.values(by).map(x=>({...x,...(noOpen[x.name]||{noOpenCount:0,noOpenKnown:0,noOpenCurrentStreak:0,noOpenBestStreak:0,noOpenStreaks:0,noOpenRate:null}),weightedWins:x.weightedWins||0,weightedWinRate:x.weightedGames?Math.round(x.weightedWins*100/x.weightedGames):null,hands:x.hands||0,avgHand:x.hands?Math.round(x.points*10/x.hands)/10:0,roundWinRate:x.hands?Math.round((x.roundWins||0)*100/x.hands):0,worstHand:x.worstHand||0,bestGame:x.bestGame??0,cleanGames:x.cleanGames||0,winRate:x.games?Math.round(x.wins*100/x.games):0,chosenLossRate:x.chosen?Math.round(x.chosenLosses*100/x.chosen):0})),games);
}
