function awardDetailModal(icon,title,names){const info=AWARD_INFO[icon];if(!info)return;const rows=names.map(n=>{const items=info.items(n),shown=items.slice(0,40);return `<h3 class="award-person">${esc(n)}</h3>${items.length?`<div class="award-items">${shown.map(x=>`<div class="award-item${x.best?' best':''}"><span class="award-when">${x.when}${x.round?` · ${lt('mano','round','el')} ${x.round}`:''}</span>${x.contract?`<span class="award-contract">${x.contract}</span>`:''}<span class="award-detail">${x.detail}</span>${x.timelineHtml||''}</div>`).join('')}${items.length>shown.length?`<p class="subtle">${lt('e altre','and','ve')} ${items.length-shown.length}</p>`:''}</div>`:`<p class="subtle">${lt('Nessuna mano o partita da mostrare.','Nothing to show.','Gösterilecek bir şey yok.')}</p>`}`;}).join('');closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><p class="eyebrow">Hall of Fame</p><h2>${icon} ${esc(title)}</h2><p class="award-meaning"><strong>${lt('Cosa significa','What it means','Anlamı')}:</strong> ${info.meaning()}</p><p class="award-how"><strong>${lt('Come si calcola','How it is calculated','Nasıl hesaplanır')}:</strong> ${info.how()}</p>${rows}<button class="ghost" id="modal-cancel">← ${lt('Statistiche','Statistics','İstatistikler')}</button></div></div>`);const back=statsReturn;document.querySelector('#modal-cancel').onclick=()=>{statsReturn=back;statisticsModal();};}
function playerStatisticDetail(name,key){
 const x=statisticsData().find(p=>p.name===name);if(!x)return null;
 const extra=extraStatisticDetail(name,key,x);if(extra)return extra;
 if(key==='chosenLast')return {title:lt('Autogol','Own goal','Kendi kalesine'),meaning:AWARD_INFO['💀'].meaning(),how:AWARD_INFO['💀'].how(),value:x.chosenLast,items:AWARD_INFO['💀'].items(name)};
 const specs={
  noOpenCount:[lt('Mani senza aprire','Rounds not opened','Açamadan biten eller'),lt('Numero di mani in cui il contratto non è stato completato.','Rounds where the contract was not completed.','Kontratın tamamlanmadığı eller.'),lt('Solo mani con informazione registrata; le precedenti sono sconosciute.','Only rounds with recorded status; old rounds are unknown.','Yalnızca durumu kayıtlı eller.')],
  noOpenRate:[lt('% senza aprire','Not opened %','Açamama %'),lt('Quota di mani senza apertura fra quelle con dato disponibile.','Share of known rounds without opening.','Bilinen eller içinde açılamayan oranı.'),`${x.noOpenCount}/${x.noOpenKnown} × 100`],
  noOpenBestStreak:[lt('Serie massima senza aprire','Longest no-open streak','En uzun açamama serisi'),lt('Massimo numero di mani consecutive senza completare il contratto.','Longest consecutive failure to complete the contract.','Kontrat tamamlanmadan geçen en uzun seri.'),lt('Le mani senza informazione interrompono il conteggio; non sono considerate aperture riuscite.','Unknown rounds break streak counting without being treated as successful openings.','Bilinmeyen eller seriyi keser.')],
  noOpenCurrentStreak:[lt('Serie attuale senza aprire','Current no-open streak','Güncel açamama serisi'),lt('Mani consecutive senza aprire nella parte più recente dello storico.','Consecutive failures to open in the latest known history.','Son geçmişte arka arkaya açılamayan eller.'),lt('Una mano aperta o senza dato interrompe la serie.','An opened or unknown round ends the streak.','Açılan ya da bilinmeyen el seriyi bitirir.')],
  noOpenStreaks:[lt('Serie senza aprire','No-open streaks','Açamama serileri'),lt('Numero di sequenze di almeno una mano senza aprire.','Number of sequences of at least one uncompleted contract.','En az bir açılamayan elden oluşan seriler.'),lt('Ogni nuova sequenza dopo una interruzione conta una volta.','Each new run after an interruption counts once.','Her kesintiden sonraki seri bir kez sayılır.')],
  games:[lt('Partite','Games','Oyunlar'),lt('Partite concluse a cui hai partecipato.','Completed games you participated in.','Katıldığınız tamamlanmış oyunlar.'),lt('Conta le partite concluse; quelle in corso non contano.','Counts completed games; ongoing games are excluded.','Tamamlanmış oyunları sayar; devam edenler hariç.')],
  weightedWins:[lt('Punti classifica','Standings points','Sıralama puanı'),lt('Più alto è meglio. Premia piazzamento e durata, non è il punteggio delle carte.','Higher is better. Rewards placement and duration, not card scores.','Yüksek daha iyi. Sıra ve süreyi ödüllendirir; kart puanı değildir.'),lt('Per ogni partita: mani × 100%, 60%, 40%, 20%, 0% dal 1° al 5°, arrotondato; poi somma. Pari merito: stessa posizione e punti. Storico incompleto escluso.','Each game: rounds × 100%, 60%, 40%, 20%, 0% for 1st–5th, rounded; then summed. Ties share rank and points. Incomplete history excluded.','Her oyun: el × %100, %60, %40, %20, %0, 1–5. sıraya göre yuvarlanıp toplanır. Eşitlikte aynı sıra ve puan. Eksik geçmiş hariç.')],
  weightedWinRate:[lt('% punti ottenuti','Points earned %','Kazanılan puan %'),lt('Quota dei punti classifica ottenuti rispetto a vincere tutte le partite. Più alto è meglio; non è la percentuale di vittorie.','Share of standings points earned compared with winning every game. Higher is better; not the win rate.','Tüm oyunları kazanarak elde edilebilecek puan oranı. Yüksek daha iyi; galibiyet oranı değildir.'),`${x.weightedWins} ÷ ${x.weightedGames||0} × 100 = ${x.weightedWinRate==null?'—':x.weightedWinRate+'%'} · ${lt('arrotondato; solo partite con durata disponibile','rounded; only games with known duration','yuvarlanır; süresi bilinen oyunlar')}`],
  wins:[lt('Vittorie','Wins','Galibiyet'),lt('Partite terminate al primo posto nella classifica registrata. Più alto è meglio.','Games finished first in the recorded standings. Higher is better.','Kayıtlı sıralamada birinci biten oyunlar. Yüksek daha iyi.'),lt('Conta i primi posti registrati, senza pesare la durata.','Counts recorded first places without duration weighting.','Kayıtlı birincilikleri süre ağırlığı olmadan sayar.')],
  seconds:[lt('Secondi posti','Second places','İkincilik'),lt('Partite terminate al secondo posto registrato.','Games finished second in the recorded standings.','Kayıtlı sıralamada ikinci biten oyunlar.'),lt('Conta i secondi posti, senza pesare la durata.','Counts second places without duration weighting.','İkincilikleri süre ağırlığı olmadan sayar.')],
  thirds:[lt('Terzi posti','Third places','Üçüncülük'),lt('Partite terminate al terzo posto registrato.','Games finished third in the recorded standings.','Kayıtlı sıralamada üçüncü biten oyunlar.'),lt('Conta i terzi posti, senza pesare la durata.','Counts third places without duration weighting.','Üçüncülükleri süre ağırlığı olmadan sayar.')],
  winRate:[lt('% vittorie','Win rate','Galibiyet oranı'),lt('Quota delle partite vinte. Più alto è meglio. Una mini partita conta come una completa.','Share of games won. Higher is better. A mini game counts as one full game.','Kazanılan oyun oranı. Yüksek daha iyi. Kısa ve tam oyun birer oyun sayılır.'),`${x.wins} ÷ ${x.games} × 100 = ${x.winRate}% · ${lt('arrotondato','rounded','yuvarlanır')}`],
  roundWins:[lt('Mani vinte','Rounds won','Kazanılan el'),lt('Mani chiuse come vincitore. Più alto è meglio.','Rounds closed as winner. Higher is better.','Kazanan olarak bitirilen eller. Yüksek daha iyi.'),lt('Conta il vincitore registrato di ogni mano, non deduce la vittoria dai soli punti zero.','Counts each recorded round winner, not inferred just from zero points.','Kayıtlı el kazananını sayar; yalnızca sıfır puandan çıkarılmaz.')],
  points:[lt('Punti di gioco','Game points','Oyun puanı'),lt('Somma dei punteggi delle carte nelle partite concluse. Meno è meglio, ma cresce con le mani giocate. Non sono punti classifica.','Sum of card scores in completed games. Lower is better, but grows with rounds played. Not standings points.','Tamamlanmış oyunların kart puanı toplamı. Az daha iyi, oynanan ellerle artar. Sıralama puanı değildir.'),lt('Somma i totali finali registrati delle partite, inclusi raddoppi e penalità.','Sums recorded final game totals, including multipliers and penalties.','Kayıtlı oyun toplamları; çarpan ve cezalar dahil.')],
  infractions:[lt('Penalità','Penalties','Cezalar'),lt('Numero di infrazioni, non punti di penalità. Meno è meglio.','Number of infractions, not penalty points. Lower is better.','İhlal sayısı, ceza puanı değil. Az daha iyi.'),lt('Somma le infrazioni registrate nelle mani. Ogni infrazione vale 50 punti nel punteggio di gioco.','Sums recorded round infractions. Each infraction adds 50 game points.','Ellerdeki ihlallerin toplamı; her ihlal oyun puanına 50 ekler.')],
  podiums:[lt('Podi','Podiums','Podyum'),lt('Partite finite tra i primi tre. Più alto è meglio; con due o tre giocatori tutti sono sul podio.','Games finished in the top three. Higher is better; with two or three players everyone is on the podium.','İlk üçte biten oyunlar. Yüksek daha iyi; iki veya üç oyuncuda herkes podyumdadır.'),lt('Conta primo, secondo e terzo posto registrati.','Counts recorded first, second and third places.','Kayıtlı birinci, ikinci ve üçüncü sıraları sayar.')],
  avgHand:[lt('Media a mano','Average per round','El başına ortalama'),lt('Punti di gioco medi per mano. Meno è meglio; tiene conto del numero di mani.','Average game points per round. Lower is better; accounts for rounds played.','El başına ortalama oyun puanı. Az daha iyi; el sayısını dikkate alır.'),`${x.points} ÷ ${x.hands} = ${decimalText(x.avgHand)} · ${lt('arrotondato a un decimale; raddoppi e penalità inclusi','rounded to one decimal; multipliers and penalties included','bir ondalığa yuvarlanır; çarpan ve cezalar dahil')}`],
  roundWinRate:[lt('% mani vinte','Rounds won %','Kazanılan el %'),lt('Quota delle mani vinte tra quelle giocate. Più alto è meglio.','Share of played rounds won. Higher is better.','Oynanan eller içinde kazanılanların oranı. Yüksek daha iyi.'),`${x.roundWins} ÷ ${x.hands} × 100 = ${x.roundWinRate}% · ${lt('arrotondato','rounded','yuvarlanır')}`],
  worstHand:[lt('Peggior mano','Worst round','En kötü el'),lt('Il punteggio di gioco più alto in una singola mano. Meno è meglio. È una mano, non una partita.','Highest game score in one round. Lower is better. One round, not a game.','Tek eldeki en yüksek oyun puanı. Az daha iyi. Oyun değil, tek el.'),lt('Massimo dei totali delle mani, dopo raddoppi e penalità. Sotto trovi la mano che ha prodotto questo valore.','Maximum recorded round total after multipliers and penalties. Its source round is listed below.','Çarpan ve cezalar sonrası en yüksek el toplamı. Kaynak el aşağıda.')],
  bestGame:[lt('Miglior partita','Best game','En iyi oyun'),lt('La partita con il totale di gioco più basso. Meno è meglio, ma una partita corta è favorita: confronta solo durate uguali. Non indica la vittoria più importante.','Game with the lowest total game score. Lower is better, but shorter games are favored: compare equal lengths. Not the most important victory.','En düşük toplam oyun puanlı oyun. Az daha iyi; kısa oyun avantajlıdır: aynı uzunlukları karşılaştırın. En önemli galibiyet değildir.'),lt('Minimo dei totali finali. Elenco delle partite con durata e miglior totale separato per ciascuna durata.','Minimum final total. Games listed with duration and best total separately for each length.','En düşük oyun toplamı. Oyun süresi ve her süre için ayrı en iyi toplam gösterilir.')],
  cleanGames:[lt('Partite pulite','Clean games','Temiz oyunlar'),lt('Partite senza infrazioni registrate. Più alto è meglio.','Games without recorded infractions. Higher is better.','Kayıtlı ihlal olmayan oyunlar. Yüksek daha iyi.'),lt('Conta le partite nelle quali nessuna mano ha penalità per questo giocatore; dati mancanti di penalità sono letti come zero.','Counts games with no recorded round infractions for this player; missing infraction values are treated as zero.','Bu oyuncunun hiçbir elde kayıtlı ihlali olmayan oyunları sayar; eksik ihlal değeri sıfır sayılır.')]
 };
 const spec=specs[key];if(!spec)return null;
 const games=evGames().filter(g=>g.players.includes(name));
 let items=[];
 if(['roundWins','roundWinRate','infractions','worstHand'].includes(key)){
  items=evRoundItems(name,(g,r,ri,i)=>{const score=Number(r.results?.[i]?.total)||0,inf=Number(r.results?.[i]?.infractions)||0,won=evRoundWinner(r)===i;
   if(key==='roundWins'&&!won||key==='infractions'&&!inf||key==='worstHand'&&score!==x.worstHand)return null;
   return {count:key==='infractions'?inf:key==='worstHand'?score:won?1:0,detail:`${score} ${pl(score,'punti di gioco','game points','oyun puanı')} · ${won?lt('mano vinta','round won','el kazanıldı'):lt('mano non vinta','round not won','el kazanılmadı')}${inf?` · ${inf} ${pl(inf,'penalità','penalties','ceza')}`:''} · ${g.rounds.length} ${pl(g.rounds.length,'mani nella partita','rounds in game','oyundaki el')}`};});
 }else{
  items=games.flatMap(g=>{const ranking=evRanking(g),pos=ranking.findIndex(r=>r.name===name),score=Number(ranking[pos]?.total)||0,n=g.rounds?.length||0,clean=!(g.rounds||[]).some(r=>Number(r.results?.[g.players.indexOf(name)]?.infractions)||0),weighted=weightedGameResult(g,ranking);
   if(key==='wins'&&pos!==0||key==='seconds'&&pos!==1||key==='thirds'&&pos!==2||key==='podiums'&&pos>2||key==='cleanGames'&&!clean)return[];
   const count=key==='weightedWins'||key==='weightedWinRate'?weighted.points[name]||0:key==='points'||key==='bestGame'||key==='avgHand'?score:1;
   return [{when:fmtDateTime(g.startedAt),count,best:key==='bestGame'&&score===x.bestGame,detail:`${n} ${pl(n,'mani','rounds','el')} · ${key==='weightedWins'||key==='weightedWinRate'?ranking.filter(r=>(Number(r.total)||0)<score).length+1:pos+1}° · ${score} ${pl(score,'punti di gioco','game points','oyun puanı')}${key==='weightedWins'||key==='weightedWinRate'?` · ${weighted.weight?`${count} ${pl(count,'punti classifica','standings points','sıralama puanı')}`:lt('durata incompleta: esclusa','incomplete duration: excluded','eksik süre: hariç')}`:''}`}];
  });
 }
 const bestByLength=key==='bestGame'?Object.entries(games.reduce((acc,g)=>{const n=g.rounds?.length||0,score=Number(evRanking(g).find(r=>r.name===name)?.total)||0;acc[n]=acc[n]==null?score:Math.min(acc[n],score);return acc;},{})).map(([n,v])=>`${n} ${pl(n,'mani','rounds','el')}: ${v} ${pl(v,'punti','points','puan')}`).join(' · '):'';
 return {title:spec[0],meaning:spec[1],how:spec[2],value:x[key],items,bestByLength};
}

function statisticTile(name,key,value,label){
 const percent=['weightedWinRate','winRate','roundWinRate','cleanRate','finishRate'].includes(key);
 const formatted=value==null?'—':decimalText(value)+(percent?'%':'');
 return `<button type="button" data-player-stat="${key}" data-player-name="${esc(name)}"><b>${formatted}</b>${esc(label)}</button>`;
}
// I dati restano tutti consultabili, ma sono raggruppati per significato e non mostrati come 25 pulsanti piatti.
function playerOverviewView(x){
 const tile=(key,label)=>statisticTile(x.name,key,x[key],label);
 const section=(title,description,summary,items,open=false)=>`<details class="player-stat-section" data-section-id="${esc(x.name+":"+title)}" ${open?'open':''}><summary><span><strong>${title}</strong><small>${description}</small></span><span class="stat-summary">${summary}</span></summary><div class="player-stats">${items}</div></details>`;
 const pos=section(lt('Posizionamenti','Placements','Sıralamalar'),
   lt('Vittorie, podi e punti di classifica','Wins, podiums and standings points','Galibiyetler, podyumlar ve sıralama puanı'),
   `${x.wins} ${lt('vittorie','wins','galibiyet')} · ${x.podiums} ${lt('podi','podiums','podyum')}`,
   tile('wins',lt('Vittorie','Wins','Galibiyetler'))+tile('seconds',lt('Secondi posti','Second places','İkincilikler'))+tile('thirds',lt('Terzi posti','Third places','Üçüncülükler'))+
   tile('podiums',lt('Podi','Podiums','Podyumlar'))+tile('winRate',lt('% vittorie','Win rate','Galibiyet %'))+tile('weightedWins',lt('Punti classifica','Standings points','Sıralama puanı'))+tile('weightedWinRate',lt('% punti ottenuti','Points earned %','Kazanılan puan %')));
 const noOpen=section(lt('Apertura del contratto','Contract opening','Kontrat açılışı'),lt('Solo mani con dato registrato','Recorded rounds only','Yalnızca kaydedilen eller'),x.noOpenKnown?`${x.noOpenCount} ${lt('senza aprire','not opened','açılmayan')}`:'—',tile('noOpenCount',lt('Mani senza aprire','Not opened','Açılmayan eller'))+tile('noOpenRate',lt('% senza aprire','Not opened %','Açamama %'))+tile('noOpenBestStreak',lt('Serie massima','Longest streak','En uzun seri'))+tile('noOpenCurrentStreak',lt('Serie attuale','Current streak','Güncel seri'))+tile('noOpenStreaks',lt('Numero di serie','Streak count','Seri sayısı')));
 const rounds=section(lt('Mani e punteggi','Rounds and scores','Eller ve puanlar'),
   lt('Rendimento nel gioco','Playing performance','Oyun performansı'),
   `${x.roundWins} ${lt('mani vinte','rounds won','kazanılan el')}`,
   tile('roundWins',lt('Mani vinte','Rounds won','Kazanılan el'))+tile('roundWinRate',lt('% mani vinte','Rounds won %','Kazanılan el %'))+
   tile('points',lt('Punti di gioco','Game points','Oyun puanı'))+tile('avgHand',lt('Media a mano','Average per round','El başına ortalama'))+
   tile('bestGame',lt('Miglior partita','Best game','En iyi oyun'))+tile('worstHand',lt('Peggior mano','Worst round','En kötü el'))+tile('chosenLast',lt('Autogol','Own goal','Kendi kalesine')));
 const accuracy=section(lt('Regolarità','Consistency','İstikrar'),
   lt('Penalità e partite senza errori','Penalties and clean games','Cezalar ve temiz oyunlar'),
   `${x.infractions} ${lt('penalità','penalties','ceza')}`,
   tile('infractions',lt('Penalità','Penalties','Cezalar'))+tile('cleanGames',lt('Partite pulite','Clean games','Temiz oyunlar')));
 const advanced=section(lt('Momenti e approfondimenti','Highlights and deep dives','Öne çıkanlar ve ayrıntılar'),
   lt('Sorpassi, finali, avversari, contratti e altri indicatori','Comebacks, finishes, opponents, contracts and more','Dönüşler, finaller, rakipler ve daha fazlası'),
   lt('Apri dettagli','Open details','Ayrıntıları aç'),
   extraStatisticTiles(x)+`<button type="button" class="player-breakdown-button" data-player-breakdown="${esc(x.name)}">${lt('Analisi per durata e contratto','Analysis by length and contract','Süre ve sözleşmeye göre analiz')} ›</button>`);
 return `<div class="player-score-summary" aria-label="${lt('Riepilogo','Summary','Özet')}"><div><strong>${decimalText(x.weightedWins)}</strong><small>${lt('Punti classifica','Standings points','Sıralama puanı')}</small></div><div><strong>${x.wins}</strong><small>${lt('Vittorie','Wins','Galibiyetler')}</small></div><div><strong>${x.games}</strong><small>${pl(x.games,'partite','games','oyun')}</small></div></div><div class="player-stat-sections">${pos}${rounds}${noOpen}${accuracy}${advanced}</div>`;
}

function playerBestGameLength(x){return [...new Set(evGames().filter(g=>g.players.includes(x.name)&&(Number(evRanking(g).find(r=>r.name===x.name)?.total)||0)===x.bestGame).map(g=>g.rounds?.length||0))].sort((a,b)=>a-b).join('/');}
function playerStatisticModal(name,key){
 const info=playerStatisticDetail(name,key);if(!info)return;
 closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><p class="eyebrow">${esc(name)}</p><h2>${esc(info.title)} · ${info.value==null?'—':decimalText(info.value)}${['weightedWinRate','winRate','roundWinRate','cleanRate','finishRate'].includes(key)&&info.value!=null?'%':''}</h2><p class="award-meaning"><strong>${lt('Cosa significa','What it means','Anlamı')}:</strong> ${info.meaning}</p><p class="award-how"><strong>${lt('Come si calcola','How it is calculated','Nasıl hesaplanır')}:</strong> ${info.how}</p>${info.bestByLength?`<p class="winner-help">${info.bestByLength}</p>`:''}<h3>${lt('Dati usati nel calcolo','Data used in the calculation','Hesaplamada kullanılan veriler')}</h3><div class="award-items">${info.items.map(item=>`<div class="award-item${item.best?' best':''}"><span class="award-when">${esc(item.when)}${item.round?` · ${lt('mano','round','el')} ${item.round}`:''}</span>${item.contract?`<span class="award-contract">${item.contract}</span>`:''}<span class="award-detail">${esc(item.detail)}</span></div>`).join('')||`<p class="subtle">${lt('Nessun dato che contribuisce al valore.','No contributing data.','Katkıda bulunan veri yok.')}</p>`}</div><button class="ghost" id="modal-cancel">← ${lt('Statistiche','Statistics','İstatistikler')}</button></div></div>`);
 const back=statsReturn;document.querySelector('#modal-cancel').onclick=()=>{statsReturn=back;statisticsModal();};
}

function playersByStanding(a){return [...a].sort((x,y)=>(statsFilter.order==='strength'?(y.strength||1000)-(x.strength||1000):0)||(y.weightedWins||0)-(x.weightedWins||0)||y.wins-x.wins||y.seconds-x.seconds||y.thirds-x.thirds||x.points-y.points||String(x.name).localeCompare(String(y.name),'it'));}
function isAlwaysSecond(x){return x.games>=3&&x.wins===0&&x.seconds*3>=x.games*2;}
function unstoppableLeaders(a){const leaders=statisticLeaders(a,'bestRoundStreak',{eligible:x=>x.bestRoundStreak>=2});return leaders.length*2<a.length?leaders:[];}
function statisticLeaders(a,field,{min=false,eligible=()=>true}={}){const pool=a.filter(eligible);if(!pool.length)return[];const value=min?Math.min(...pool.map(x=>x[field])):Math.max(...pool.map(x=>x[field]));return pool.filter(x=>x[field]===value);}
function uniqueStatisticLeader(a,field,options){const leaders=statisticLeaders(a,field,options);return leaders.length===1?leaders:[];}
function awardLine(icon,title,leaders,field,suffix='',keepZero=false){if(!leaders.length)return'';if(!keepZero&&!(Number(leaders[0][field])>0))return'';if(title&&typeof title==='object')title=leaders.every(x=>isFemale(x.name))?title.f:title.m;return `<button class="award-tile" data-award="${esc(icon)}" data-award-title="${esc(title)}" data-award-names="${esc(JSON.stringify(leaders.map(x=>x.name)))}"><span class="award-icon">${icon}</span><strong class="award-title">${title}</strong><span class="award-who">${leaders.map(x=>esc(x.name)).join(' · ')}</span><span class="award-val">${leaders[0][field]}${one(leaders[0][field],suffix)}</span><span class="award-more">${lt('Dettagli','Details','Ayrıntılar')} ›</span></button>`;}
// var: la legge statisticsModal già prima che il programma arrivi qui
var statsReturn=null;
function statsPosition(){const m=document.querySelector('#modal .modal');if(!m||!document.querySelector('#modal [data-stat-tab]'))return null;return {scroll:Number(m.scrollTop)||0,tab:document.querySelector('#modal [data-stat-tab].active')?.dataset?.statTab||null,expanded:[...document.querySelectorAll('.player-stat-section[open]')].map(x=>x.dataset.sectionId)};}
function restoreStatsPosition(pos){if(!pos)return;if(pos.tab){document.querySelectorAll('[data-stat-tab]').forEach(t=>t.classList.toggle('active',t.dataset.statTab===pos.tab));document.querySelectorAll('[data-stat-pane]').forEach(p=>{p.hidden=p.dataset.statPane!==pos.tab;});}const m=document.querySelector('#modal .modal');if(m)m.scrollTop=pos.scroll;if(pos.expanded)document.querySelectorAll('.player-stat-section').forEach(x=>x.open=pos.expanded.includes(x.dataset.sectionId));}
function standingsExplanationModal(){const back=statsPosition();closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><h2>${lt('Come funziona la classifica','How the standings work','Sıralama nasıl çalışır')}</h2>${lt('<p class="subtle stat-order">Ordine: punti classifica, poi vittorie, secondi posti, terzi posti, meno punti. La classifica dipende dal numero di giocatori: il primo riceve il 100% delle mani, gli intermedi il 60%, 40% o 20% secondo la posizione, il giocatore ultimo riceve sempre 0 (anche quando più giocatori sono ultimi a pari merito). I punti sono arrotondati. I primi a pari merito ricevono gli stessi punti. Lo storico incompleto resta escluso.</p>','<p class="subtle stat-order">Order: standings points, then wins, second places, third places, fewest points. Scores depend on the number of players: first earns 100% of rounds, intermediate places earn 60%, 40% or 20%, and last place always earns zero, even when tied for last. Values are rounded. Tied winners receive the same points. Incomplete games are excluded.</p>','<p class="subtle stat-order">Sıra: zafer puanı, sonra galibiyet, ikincilik, üçüncülük, en az puan. Puanlar oyuncu sayısına bağlıdır: birinci el sayısının %100 kadar puan alır, orta sıralar %60, %40 veya %20 alır, sonuncu her zaman 0 alır. Eşit birinciler aynı puanı alır; eksik oyunlar dahil edilmez.</p>') }<button class="ghost" id="modal-cancel">← ${lt('Giocatori','Players','Oyuncular')}</button></div></div>`);document.querySelector('#modal-cancel').onclick=()=>{statsReturn=back;statisticsModal();};}
// Il link e' pubblico e di sola consultazione: nessun token privato o identificativo proprietario.
