function redactLocalExport(value){if(Array.isArray(value))return value.map(redactLocalExport);if(value&&typeof value==='object'){const out={};for(const [key,item] of Object.entries(value))out[key]=/token|key/i.test(key)?'***':redactLocalExport(item);return out;}return value;}
